using Inventory.Legacy;

namespace Inventory;

/// <summary>Writes point-in-time stock snapshots.</summary>
public sealed class SnapshotWriter
{
    private readonly IInventoryStore _store;
    private int _count;

    public SnapshotWriter()
        : this(new InMemoryInventoryStore())
    {
    }

    public SnapshotWriter(IInventoryStore store)
    {
        _store = store ?? throw new ArgumentNullException(nameof(store));
    }

    public void Write(StockItem item)
    {
        _store.Save(item.Sku, item.OnHand, item.Reserved);
        _count++;
    }

    public int Count => _count;
}
